/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MaxTab_01.setSelectedTabIndex("1");
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.cm.PanelToGroupBox(panel_Top2);

        // init set common code
        await scwin.setCode();

        // 수량변경,종목명변경 접수(신청) 내역 조회
        // 처음 화면 로딩시에는 수량변경의 신청내역(중도상환)만 조회한다.
        await scwin.listQtyAppl("", "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08021.onpageload" });
    }
};

/**
 * @method
