/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        $c.lce.fn_CloseNoData();

        // 조회버튼 클릭(수량변경)
        if ($c.ut.trim(txb_SearchIsuCd.getValue()) === "") {
            txb_SearchIsuCd.setValue("");
            txb_SearchIsuNm.setValue("");
        }
        await scwin.listQtyAppl(cmb_ISUR_CD.getValue(), txb_SearchIsuCd.getValue());
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08021.btn_Search_onclick" });
    }
};

