 */
scwin.btn_New_onclick = async function() {
    try {
        // 신규 버튼 클릭

        // 수량변경
        if (MaxTab_01.getSelectedTabIndex() === "1") {
            // 수량변경 - 발행 및 상장내역 신규 화면 오픈
            if (txb_SearchIsuCd.getValue() === "") {
                await $c.win.alert("[종목]을 선택하세요.");
            } else {
                await scwin.popQtyIsur("N", -1, ""); //-1은 의미 없음

            }

            // 종목명변경

        } else {
            // 종목명변경 - 종목명변경 상장내역 신규 화면 오픈
            if (txb_SearchIsuCd2.getValue() === "") {
                await $c.win.alert("[종목]을 선택하세요.");
            } else {
                await scwin.popIsuNmChg("N", -1, ""); //-1은 의미 없음

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08021.btn_New_onclick" });
    }
};

