/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        // Save to Excel (수량변경)
        const isExcelDown = false;
        let xls_path;
        let countAppl = 0;
        let countIsur = 0;
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        // 파일형식 today_화면명.xls
        const xls_path = $c.session.getExcelDownPath() + today + "_변경상장_STF08021.xls";
        if (MaxTab_01.getSelectedTabIndex() === "1") {
            countAppl = dts_Qty_ApplDtl.getRowCount();
            countIsur = dts_Qty_IsurDtl.getRowCount();
            // 28은 파일저장 대화창 나타내고, 40은 xls_path에 옵션으로 sheet를 붙이는 의미인 것 같음
            if (countAppl > 0 && countIsur > 0) {
                $c.data.saveExcel(grd_Qty_IsurDtl, "수량변경 발행및상장내역", false, false, false, xls_path);
                $c.data.downloadGridViewExcel(grd_Qty_ApplDtl, {fileName: "수량변경 신청내역", sheetName: xls_path, type: 40});
            } else if (countAppl > 0 && countIsur === 0) {
                $c.data.downloadGridViewExcel(grd_Qty_ApplDtl, {fileName: "수량변경 신청내역", type: 8});
            } else if (countAppl === 0 && countIsur > 0) {
                $c.data.downloadGridViewExcel(grd_Qty_IsurDtl, {fileName: "수량변경 발행및상장내역", type: 8});
            } else {
                await $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
            }
        } else {
            countAppl = dts_Itm_ApplDtl.getRowCount();
            countIsur = dts_Itm_IsurDtl.getRowCount();

            // 28은 파일저장 대화창 나타내고, 40은 xls_path에 옵션으로 sheet를 붙이는 의미인 것 같음
            if (countAppl > 0 && countIsur > 0) {
                $c.data.saveExcel(grd_Itm_ListDtl, "변경 상장내역", false, false, false, xls_path);
                $c.data.downloadGridViewExcel(grd_Itm_ApplDtl, {fileName: "병경 신청내역", sheetName: xls_path, type: 40});
            } else if (countAppl > 0 && countIsur === 0) {
                $c.data.downloadGridViewExcel(grd_Itm_ApplDtl, {fileName: "변경 신청내역", type: 8});
            } else if (countAppl === 0 && countIsur > 0) {
                $c.data.downloadGridViewExcel(grd_Itm_ListDtl, {fileName: "변경 상장내역", type: 8});
            } else {
                await $c.win.alert("[엑셀]로 저장하려는 데이터가 없습니다.");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08021.btn_Excel_onclick" });
    }
};

