 * @description cmb_ISUR_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ISUR_CD_onselchange = async function() {
    try {
        // 수량변경 재조회
        if (!scwin.v_QtyApplRowClicked) {
            if ($c.ut.trim(txb_SearchIsuCd.getValue()) === "") {
                txb_SearchIsuCd.setValue("");
                txb_SearchIsuNm.setValue("");
            }
            await scwin.listQtyAppl(cmb_ISUR_CD.getValue(), txb_SearchIsuCd.getValue());
            await scwin.listSync();
        } else {
            scwin.v_QtyApplRowClicked = false;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08021.cmb_ISUR_CD_onselchange" });
    }
};

