/**
 * @method
 * @name getParIsur
 * @description 상장신청 발행기관 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (MaxTab_01.getSelectedTabIndex() === "1") {
        arrPar[0] = txb_SearchIsuCd.getValue(); // 코드값을 포함할 컨트롤
        arrPar[1] = txb_SearchIsuNm.getValue(); // 명칭값을 포함할 컨트롤

    } else {
        arrPar[0] = txb_SearchIsuCd2.getValue(); // 코드값을 포함할 컨트롤
        arrPar[1] = txb_SearchIsuNm2.getValue(); // 명칭값을 포함할 컨트롤

    }
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        if (MaxTab_01.getSelectedTabIndex() === "1") {
            txb_SearchIsuCd.setValue(arrPar[0].ISU_CD);
            txb_SearchIsuNm.setValue(arrPar[0].ISU_KOR_ABBRV);
            cmb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        } else {
            txb_SearchIsuCd2.setValue(arrPar[0].ISU_CD);
            txb_SearchIsuNm2.setValue(arrPar[0].ISU_KOR_ABBRV);
            cmb_ISUR_CD2.setValue(arrPar[0].ISUR_CD);
        }
    }
};

/**
 * @method
 * @name popQtyAppl
 * @description 수량변경 >  신청내역(중도상환) > 팝업
 * @param {*} kind kind
 * @param {*} rowno rowno
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popQtyAppl = async function(kind, rowno, colid) {
    // 신규저장, 수정 구분
    scwin.vQtyApplKind = kind;

    // 신규 (신청내역)
    let i = 0;
    scwin.clickAcptNo = dts_Qty_ApplDtl.getCellData(rowno, "ACPT_NO");
    scwin.v_UpdQtyApplParam[i++] = dts_Qty_ApplDtl.getCellData(rowno, "ISU_CD");
    scwin.v_UpdQtyApplParam[i++] = dts_Qty_ApplDtl.getCellData(rowno, "ISUR_CD");
    const options = {
        id: "" + scwin.pQtyApplDtlID + "",
        title: "수량변경 신청내역 세부내역",
        type: "browserPopup",
        width: "720px",
        height: "260px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../etn/" + scwin.pQtyApplDtlID + ".gfm", options);
};

/**
 * @method
 * @name popQtyIsur
 * @description 수량변경 > 발행 및 상장내역 > 팝업
 * @param {*} kind kind
 * @param {*} rowno rowno
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popQtyIsur = async function(kind, rowno, colid) {
    // 신규저장, 수정 구분
    scwin.vQtyIsurKind = kind;
    if (kind === "N") {
        const options = {
            id: "" + scwin.pQtyIsurDtlID + "",
            title: "수량변경 발행 및 상장내역 신규",
            type: "browserPopup",
            width: "720px",
            height: "260px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../etn/" + scwin.pQtyIsurDtlID + ".gfm", options);
    } else if (kind === "U") {
        // 업무처리번호
        let i = 0;
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "BZ_PROCS_NO");
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "ISUR_CD");
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "DISCLS_YN");
        scwin.v_UpdQtyIsurParam[i++] = dts_Qty_IsurDtl.getCellData(rowno, "LIST_BZ_TP_CD");
        const options = {
            id: "" + scwin.pQtyIsurDtlID + "",
            title: "수량변경 발행 및 상장내역 세부내역",
            type: "browserPopup",
            width: "720px",
            height: "260px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../etn/" + scwin.pQtyIsurDtlID + ".gfm", options);
    }
};

